 {tab==='map'&&inventory&&<><div className="panel-title"><h3><MapIcon size={17}/> Plano de avance</h3><span>{scopedSpans.length} vanos <i/> {fmt(scopedSpans.reduce((a,s)=>a+s.longitud_planta_m,0)/1000,2)} km</span></div><div className="map-selection-tools"><div className="segmented selection-mode" role="group" aria-label="Modo de selección de vanos"><button type="button" aria-pressed={!multiMode} className={!multiMode?'active':''} onClick={()=>changeSelectionMode(false)}>Selección simple</button><button type="button" aria-pressed={multiMode} className={multiMode?'active':''} onClick={()=>changeSelectionMode(true)}>Selección múltiple</button></div>{multiMode&&<div className="map-selection-summary"><span aria-live="polite"><b>{multiIds.length}</b> vanos seleccionados{multiIds.filter(id=>line!=='all'&&inventory.vanos.find(s=>s.id===id)?.linea!==line).length>0&&<small>Incluye vanos de otra línea que no muestra el filtro actual.</small>}</span><div><button className="primary" disabled={!multiIds.length} onClick={openMultiEditor}>Editar seleccionados</button><button className="outline" disabled={!multiIds.length} onClick={()=>setMultiIds([])}>Limpiar selección</button></div></div>}{multiMode&&<p>Tocá los vanos para agregarlos. Tocá uno marcado nuevamente para quitarlo.</p>}</div><TraceMap data={inventory} records={records} selected={multiMode?null:selected} selectedIds={multiMode?multiIds:[]} multiple={multiMode} onSelect={selectOnMap} line={line} focus={focus} basePath={basePath} memory={mapMemory.current} onViewChange={rememberMap} poleTarget={poleTarget}/><div className="legend">{statusOptions.map(([k,v])=><span key={k}><i style={{background:colors[k as Status]}}/>{v}</span>)}{line!=='corta'&&<span className="access-key"><i aria-hidden="true"/>Piquetes 40–63 · Difícil acceso por desniveles pronunciados</span>}</div></>}
