 <div className="list-subtools"><span aria-live="polite">{dayProgress?`${visible.length} de ${dayProgress.total} vanos del día`:`${visible.length} vanos`}</span><label><SlidersHorizontal size={16}/><select aria-label="Filtrar vanos por línea" value={line} onChange={e=>setLine(e.target.value)}><option value="all">Todas las líneas</option><option value="larga">Línea larga</option><option value="corta">Línea corta · FP</option></select></label></div>
